if __name__ == "__main__":
    bad = 0
    names = set()
    for x in M:
        assert x["name"] not in names, "duplicate name " + x["name"]
        names.add(x["name"])
        text = open(os.path.join(root, x["file"])).read()
        n = text.count(x["find"])
        if n != 1:
            print(f'{x["name"]}: find string occurs {n} times in {x["file"]}', file=sys.stderr)
            bad += 1
        if x["find"] == x["replace"]:
            print(f'{x["name"]}: replace equals find', file=sys.stderr)
            bad += 1
    if bad:
        sys.exit(1)
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "mutations.json"), "w") as f:
        json.dump(M, f, indent=1, ensure_ascii=False)
        f.write("\n")
    print(len(M), "mutations")
